proc recover_cells_and_proofs_parallel*(
    tp: Taskpool,
    dataColumns: seq[ref fulu.DataColumnSidecar]):
    Result[seq[CellsAndProofs], cstring] =
  ## This helper recovers blobs from the data column sidecars parallelly
  if dataColumns.len == 0:
    return err("DataColumnSidecar: Length should not be 0")

  let
    columnCount = dataColumns.len
    blobCount = dataColumns[0].column.len

  for column in dataColumns:
    if not (blobCount == column.column.len):
      return err ("DataColumns do not have the same length")

  # spawn threads for recovery
  var
    pendingFuts = newSeq[Flowvar[Result[CellsAndProofs, void]]](blobCount)
    res = newSeq[CellsAndProofs](blobCount)
  for blobIdx in 0..<blobCount:
    var
      cellIndices = newSeq[CellIndex](columnCount)
      cells = newSeq[Cell](columnCount)
    for i in 0 ..< dataColumns.len:
      cellIndices[i] = dataColumns[i][].index
      cells[i] = dataColumns[i][].column[blobIdx]
    pendingFuts[blobIdx] =
      tp.spawn recoverCellsAndKzgProofsTask(cellIndices, cells)

  # sync threads
  for i in 0..<blobCount:
    let futRes = sync pendingFuts[i]
    if futRes.isErr:
      return err("KZG cells and proofs recovery failed")
    res[i] = futRes.get
  ok(res)

proc recover_cells_and_proofs*(
    data_columns: seq[ref fulu.DataColumnSidecar]):
    Result[seq[CellsAndProofs], cstring] =
  ## This helper recovers blobs from the data column sidecars
  if data_columns.len == 0:
    return err("DataColumnSidecar: Length should not be 0")

  let start = Moment.now()

  let
    columnCount = data_columns.len
    blobCount = data_columns[0].column.len

  for data_column in data_columns:
    if not (blobCount == data_column.column.len):
      return err ("DataColumns do not have the same length")

  var
    recovered_cps =
      newSeq[CellsAndProofs](blobCount)

  for blobIdx in 0..<blobCount:
    var
      bIdx = blobIdx
      cell_ids = newSeqOfCap[CellIndex](columnCount)
      ckzgCells = newSeqOfCap[KzgCell](columnCount)

    for col in data_columns:
      cell_ids.add col[].index

      let
        column = col[].column
        cell = column[bIdx]

      ckzgCells.add cell

    # Recovering the cells and proofs
    let recovered_cells_and_proofs =
      recoverCellsAndKzgProofs(cell_ids, ckzgCells)
    if not recovered_cells_and_proofs.isOk:
      return err("Failed to compute cells and proofs")

    recovered_cps[bIdx] =
      recovered_cells_and_proofs.get
  let finish = Moment.now()
  debug "Time taken to reconstruct sequentially", time = finish-start
  ok(recovered_cps)

